        samples.push(fromFrame(f, a, b));
      }
    }
    console.log('DEBUG court samples count:', samples.length);

    for (const [px0, py0] of samples) {
      n++;
      console.log('DEBUG sample n=' + n + ' px0=' + px0 + ' py0=' + py0);
